private int best(int[] weight, int[] value, int rem) {
    if (rem == 0) {
        return 0;
    }
    int top = 0;
    for (int i = 0; i < weight.length; i++) {
        if (weight[i] <= rem) {
            top = Math.max(top, value[i] + best(weight, value, rem - weight[i]));
        }
    }
    return top;
}

