public int unboundedKnapsack(int[] weight, int[] value, int W) {
    int[] memo = new int[W + 1];
    Arrays.fill(memo, -1);
    return best(weight, value, W, memo);
}

private int best(int[] weight, int[] value, int rem, int[] memo) {
    if (rem == 0) {
        return 0;
    }
    if (memo[rem] != -1) {
        return memo[rem];
    }
    int top = 0;
    for (int i = 0; i < weight.length; i++) {
        if (weight[i] <= rem) {
            top = Math.max(top, value[i] + best(weight, value, rem - weight[i], memo));
        }
    }
    memo[rem] = top;
    return top;
}

