public int unboundedKnapsack(int[] weight, int[] value, int W) {
    int[] dp = new int[W + 1];
    for (int w = 1; w <= W; w++) {
        for (int i = 0; i < weight.length; i++) {
            if (weight[i] <= w) {
                dp[w] = Math.max(dp[w], value[i] + dp[w - weight[i]]);
            }
        }
    }
    return dp[W];
}

