def unbounded_knapsack(self, weight: list[int], value: list[int], W: int) -> int:
    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        for i in range(len(weight)):
            if weight[i] <= w:
                dp[w] = max(dp[w], value[i] + dp[w - weight[i]])
    return dp[W]

